    // Store the current parent and child nodes of the node
    TreeNode<T> parent = node.getParent();
    TreeNode<T> child = node.getRight();

    // Set the new parent and children for the node
    node.setParent(child);
    if (child != null) {
        child.setLeft(node);
    }

    // Set the new parent and children for the parent node
    if (parent != null) {
        parent.setRight(node);
    }

    return child;
}

private TreeNode<T> rotateRight(TreeNode<T> node) {
    TreeNode<T> parent = node.getParent();
    if (parent == null) {
        // If the node is the root, we need to update the root of the tree
        root = node;
    } else {
        // If the node is not the root, we need to update the parent node's child reference
        if (parent.getLeft() == node) {
            parent.setLeft(node.getRight());
        } else {
            parent.setRight(node.getRight());
        }
    }
    // Update the node's parent and child references
    node.setParent(parent.getParent());
    parent.setParent(node);
    node.setRight(parent);
    return node;
}

private TreeNode<T> rotateRight(TreeNode<T> node) {
    // Create the new parent
    TreeNode<T> newParent = new TreeNode<T>(node.value, null, node.right, node.left);

    // Update the links of the current node and its parent
    node.right = newParent;
    newParent.parent = node.parent;

    // Update the link of the current node's parent to point to the new parent
    if (node.parent != null) {
        if (node == node.parent.left) {
            node.parent.left = newParent;
        } else {
            node.parent.right = newParent;
        }
    }

    // Update the link of the new parent's parent to point to the current node
    newParent.parent = node.parent;

    return newParent;
}

private TreeNode<T> rotateRight(TreeNode<T> node) {
    // Get the left child of the node to be rotated
    TreeNode<T> newRoot = node.left;
    // Set the left child of the node to be rotated to the right child of the left child
    node.left = newRoot.right;
    // Set the right child of the left child to the node to be rotated
    newRoot.right = node;
    // Return the new parent of the node
    return newRoot;
  }

