for (String line : lines) {
    // 4. Split the line into two parts based on the "##" separator
    String[] parts = line.split("##", 2);

    // 5. Get the thread name and thread ID from the first part
    String threadName = parts[0];
    long threadId = Long.parseLong(parts[1]);

    // 6. Get the start and end time from the second part
    String[] timeParts = parts[1].split("-");
    long startTime = Long.parseLong(timeParts[0]);
    long endTime = Long.parseLong(timeParts[1]);

    // 7. Create a new thread snapshot object and populate it with the thread name, ID, start and end time
    ThreadSnapshot threadSnapshot = new ThreadSnapshot(threadName, threadId, startTime, endTime);

    // 8. Add the thread snapshot to the list
    threadSnapshots.add(threadSnapshot);
}

