for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
    // 10. Filter the list of thread snapshots to only keep threads that are in the current time range
    List<ThreadSnapshot> filteredSnapshots = threadSnapshots.stream()
        .filter(snapshot -> timeRange.contains(snapshot.startTime) || timeRange.contains(snapshot.endTime))
        .collect(Collectors.toList());

    // 11. Create a new set to store the unique thread names in the current time range
    Set<String> uniqueThreadNames = new HashSet<>();

    // 12. Go through each snapshot in the filtered list
    for (ThreadSnapshot snapshot : filteredSnapshots) {
        // 13. Check if the thread name is already in the set
        if (!uniqueThreadNames.contains(snapshot.threadName)) {
            // 14. If not, add it to the set
            uniqueThreadNames.add(snapshot.threadName);
        }
    }

    // 15. Create a new string builder to store the output
    StringBuilder output = new StringBuilder();

    // 16. Go through each unique thread name in the set
    for (String threadName : uniqueThreadNames) {
        // 17. Get the count of thread snaphots for the current thread name
        long count = filteredSnapshots.stream()
            .filter(snapshot -> snapshot.threadName.equals(threadName))
            .count();

        // 18. Add the count and thread name to the output string
        output.append(threadName).append(": ").append(count).append("\n");
    }

    // 19. Print the output string
